from pathlib import Path
import json,html
base=Path(__file__).resolve().parent.parent
assets=json.loads((base/'QA/AudioAssets.json').read_text())
names={'swap':'Swap','reject':'Rejected move','match':'Gem shatter','create':'Special formation','bomb':'Bomb impact','line':'Directional sweep','flight':'Firebird flight','arrival':'Firebird arrival','color':'Rainbow / Living Light','mace':'Mace impact','firebird':'Firebird booster','renewal':'Sea Pearl renewal','wood':'Crate break','ice':'Ice fracture','metal':'Chain break','seal':'Runic seal break'}
rows=''.join(f'<option value="{a["name"]}">{names[a["name"]]}</option>' for a in assets)
(base/'Gameplay_Mechanics_R11_Review.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gameplay R11 — Impact Audio</title><style>
*{box-sizing:border-box}body{margin:0;background:#0c1420;color:#efdebb;font:17px/1.5 system-ui,sans-serif}main{max-width:1050px;margin:auto;padding:24px}h1{font:32px Georgia,serif;color:#e8be66}a{color:#b7dfff}section{margin:20px 0;padding:20px;border:1px solid #685238;border-radius:12px;background:#121f2b}.layout{display:grid;grid-template-columns:minmax(220px,380px) 1fr;gap:25px;align-items:start}img{width:100%;height:auto;display:block}button,select{font:inherit;color:#f0debb;background:#20394a;border:1px solid #91764b;padding:12px;border-radius:6px;margin:5px 0;max-width:100%}button{cursor:pointer}audio{width:100%;margin:18px 0}small{color:#c0c4c7}label{display:block}#status{min-height:3em} @media(max-width:700px){.layout{grid-template-columns:1fr}main{padding:14px}.portrait{max-width:380px;margin:auto}}
</style><main><h1>Gameplay R11 · Impact Audio</h1><p>Distinct sounds for the approved sandbox effects. R10 artwork, round difficulty and deterministic rules remain unchanged.</p><div class="layout"><section class="portrait"><img src="Captures/Bomb.png" alt="Actual Unity sandbox capture with the R11 audio component installed"><small>Actual Unity test capture · 576 × 1280. This still image does not demonstrate audio synchronization.</small></section><div><section><h2>Listen to the cues</h2><p>Original synthesized sounds, played individually at their gameplay gain. These are source previews, not a recording of Unity output.</p><label for="cue">Sound</label><select id="cue">'''+rows+'''</select><audio id="audio" controls preload="metadata"></audio><label><input id="damaged" type="checkbox"> First obstacle hit (lower pitch and volume)</label><p id="status" role="status"></p><button id="bomb">Preview bomb timing</button> <button id="spark">Preview Firebird timing</button> <button id="stop">Stop</button><small><p>Timing previews use the same 0.12 s charge and 0.52 s flight delays as the sandbox. Listen on your usual device before approving the mix.</p></small></section><section><h2>Try it in Unity</h2><p>Home → Development → Gameplay Mechanics Sandbox. Enable sound in Settings. Play the five rounds, then use Fixtures to compare bombs, directional pieces and stocked boosters.</p><p>Listen for a lighter first obstacle hit followed by a stronger final break. Check that cascades remain readable and the Firebird arrival matches its landing.</p><p>The existing vibration service remains connected. Physical-device vibration, speaker quality and Android performance have not been verified here.</p><a href="ImplementationReport.md">Implementation and verification</a> · <a href="../R10/Gameplay_Mechanics_R10_Review.html">R10 visual comparison</a></section></div></div></main><script>
const cue=document.querySelector('#cue'),audio=document.querySelector('#audio'),damaged=document.querySelector('#damaged'),status=document.querySelector('#status');
const path='../../../../Assets/LegendsOfRus/Resources/MechanicsAudioR11/';let timers=[],extra=[];
const materials=['wood','ice','metal','seal'];
function gain(n){return (materials.includes(n)?.4:['swap'].includes(n)?.2:n==='reject'?.22:['match','create','flight'].includes(n)?.3:n==='arrival'?.44:.48)*.65}
function stop(){timers.forEach(clearTimeout);timers=[];extra.forEach(a=>a.pause());extra=[];audio.pause();status.textContent='Stopped';}
function select(){stop();let n=cue.value;audio.src=path+n+'.wav';audio.volume=gain(n)*(damaged.checked&&materials.includes(n)?.23/.4:1);audio.preservesPitch=false;audio.playbackRate=damaged.checked&&materials.includes(n)?.82:1;status.textContent=materials.includes(n)?(damaged.checked?'First hit: muted fracture; another layer remains.':'Final break: full material impact.'):'Single cue preview';}
function play(n){const a=new Audio(path+n+'.wav');a.volume=gain(n);extra.push(a);a.play().catch(e=>status.textContent='Playback failed: '+e.message)}
cue.onchange=select;damaged.onchange=select;document.querySelector('#stop').onclick=stop;
document.querySelector('#bomb').onclick=()=>{stop();status.textContent='Charge → bomb impact at 0.12 s';timers.push(setTimeout(()=>play('bomb'),120));};
document.querySelector('#spark').onclick=()=>{stop();status.textContent='Flight → arrival at 0.52 s';play('flight');timers.push(setTimeout(()=>play('arrival'),520));};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});select();
</script></html>''')
print('Built sound review')
